document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("work"),c=document.getElementById("projectStory"),l=document.querySelectorAll("#storyBtn button"),w=document.querySelector(".scroll-section "),i=document.getElementById("storyTop"),e=document.querySelector('.point-container[data-type="viewSwitch"]');let t;t=localStorage.getItem("projectStoryTooltip"),t==="true"&&e.classList.add("display-none");const d=()=>{l.forEach(o=>{o.setAttribute("data-active","false"),o.disabled=!1})};l.forEach(o=>{o.addEventListener("click",s=>{s.preventDefault();let n=s.currentTarget,u=n.getAttribute("data-content"),p=window.scrollY;switch(d(),n.setAttribute("data-active","true"),u){case"work":a.setAttribute("data-status","show"),c.setAttribute("data-status","hide");break;case"story":a.setAttribute("data-status","hide"),c.setAttribute("data-status","show"),(!t||t==="false")&&(localStorage.setItem("projectStoryTooltip","true"),e.classList.add("display-none")),i.scrollIntoView({behavior:"smooth",block:"start"});break;default:break}n.disabled=!0})});const r=()=>{window.scrollY>100&&e.classList.add("display-none")};r(),window.addEventListener("load",r),window.addEventListener("scroll",function(s){window.scrollY>=200&&e.classList.add("display-none"),(window.scrollY<=200&&!t||t==="false")&&e.classList.remove("display-none")})});
